<template>
  <div :class="ns.be('group', 'wrap')" :style="groupStyle">
    <el-divider v-if="showDivider" margin="8px 0" />
    <div :class="ns.be('group', 'title')">
      {{ item.label }}
    </div>
  </div>
</template>

<script lang="ts">
import { computed, defineComponent } from 'vue'
import ElDivider from '@element-plus/components/divider'
import { useNamespace } from '@element-plus/hooks'

import type { CSSProperties, PropType } from 'vue'

export default defineComponent({
  components: {
    ElDivider,
  },
  props: {
    item: {
      type: Object,
      required: true,
    },
    style: {
      type: Object as PropType<CSSProperties>,
    },
    showDivider: {
      type: Boolean,
      default: true,
    },
  },
  setup(props) {
    const ns = useNamespace('select')
    const groupStyle = computed(() => {
      const positionStyle = { ...props.style }
      delete positionStyle.height
      delete positionStyle.lineHeight
      return positionStyle
    })

    return {
      ns,
      groupStyle,
    }
  },
})
</script>
